_title":"Genel Bilim Quiz","question":"Bir deneyde değiştirilmeyen ve sabit tutulan faktörlere ne denir?","options":["Bağımsız değişken","Bağımlı değişken","Kontrol değişkeni","Hipotez"],"correct_answer":"Kontrol değişkeni"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel kuram (teori) aşağıdakilerden hangisidir?","options":["Sadece bir tahmin","Kapsamlı testlerden geçmiş açıklama","Bir hipotez ile aynı şey","Kanıtlanmamış bir fikir"],"correct_answer":"Kapsamlı testlerden geçmiş açıklama"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyde ölçülen ve başka bir faktöre bağlı olarak değişen faktöre ne denir?","options":["Bağımsız değişken","Bağımlı değişken","Kontrol grubu","Hipotez"],"correct_answer":"Bağımlı değişken"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı bir deney sonucunu diğer bilim insanlarıyla paylaşmak için aşağıdakilerden hangisini yapar?","options":["Sonucu gizli tutar","Hakemli bir dergide yayınlar","Sadece öğrencilerine anlatır","Sonucu bir kitaba yazar"],"correct_answer":"Hakemli bir dergide yayınlar"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setinde en sık tekrar eden değere ne denir?","options":["Ortalama","Medyan","Mod","Aralık"],"correct_answer":"Mod"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyde iki grup arasındaki tek fark bağımsız değişken ise, bu gruplara ne denir?","options":["Kontrol ve deney grubu","Öncül ve ardıl grup","Rastgele ve seçilmiş grup","Aktif ve pasif grup"],"correct_answer":"Kontrol ve deney grubu"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı, gözlemlerine dayanarak bir açıklama önerdiğinde bu açıklamaya ne denir?","options":["Kuram","Yasa","Hipotez","Aksiyom"],"correct_answer":"Hipotez"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setindeki değerlerin ortalamadan ne kadar saptığını ölçen istatistiksel değer nedir?","options":["Medyan","Standart sapma","Mod","Aralık"],"correct_answer":"Standart sapma"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel yasa (law) aşağıdakilerden hangisini yapar?","options":["Bir olayı açıklar","Bir olayın nasıl olduğunu betimler","Yeni bir hipotez önerir","Bir kuramı çürütür"],"correct_answer":"Bir olayın nasıl olduğunu betimler"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir grafikte x eksenindeki değişken genellikle aşağıdakilerden hangisidir?","options":["Bağımlı değişken","Bağımsız değişken","Kontrol değişkeni","Sabit değer"],"correct_answer":"Bağımsız değişken"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyin sonuçları tekrarlanabilir olması neden önemlidir?","options":["Daha uzun sürer","Sonuçların güvenilir olduğunu gösterir","Daha fazla para harcanır","Daha az insan gerektirir"],"correct_answer":"Sonuçların güvenilir olduğunu gösterir"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setinde en büyük ve en küçük değer arasındaki farka ne denir?","options":["Ortalama","Medyan","Aralık (range)","Mod"],"correct_answer":"Aralık (range)"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı bir deneyin sonucunu raporlarken aşağıdakilerden hangisini yapmamalıdır?","options":["Verileri doğru rapor eder","Yöntemi açıklar","Verileri kendi hipotezini desteklemek için çarpıtır","Sonuçların sınırlamalarını belirtir"],"correct_answer":"Verileri kendi hipotezini desteklemek için çarpıtır"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel modelin amacı aşağıdakilerden hangisidir?","options":["Karmaşık bir sistemi basitleştirerek anlamak","Gerçeğin tam bir kopyasını oluşturmak","Sadece güzel görünmek","Hipotezleri çürütmek"],"correct_answer":"Karmaşık bir sistemi basitleştirerek anlamak"}