select subject, subject_title, question, options, correct_answer
from jsonb_to_recordset($btkquiz_seed$[{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir cismin sabit hızla hareket ettiği bir sistemde, cisme etki eden net kuvvet için aşağıdakilerden hangisi söylenebilir?","options":["Net kuvvet sıfırdır","Net kuvvet cisme etki eder","Net kuvvet kütle ile doğru orantılıdır","Net kuvvet hız ile doğru orantılıdır"],"correct_answer":"Net kuvvet sıfırdır"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir araba 10 saniyede 0'dan 20 m/s hıza ulaşıyorsa ivmesi kaç m/s²'dir?","options":["1 m/s²","2 m/s²","3 m/s²","0.5 m/s²"],"correct_answer":"2 m/s²"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir yay 5 N kuvvetle 0.2 m uzadığında yayın yay sabiti (k) kaç N/m'dir?","options":["10 N/m","25 N/m","20 N/m","50 N/m"],"correct_answer":"25 N/m"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir cismin kütlesi Dünya'da 60 kg ise Ay'da ağırlığı yaklaşık kaç N'dir? (g_ay ≈ 1.6 m/s²)","options":["60 N","96 N","600 N","980 N"],"correct_answer":"96 N"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"İki direnç (6Ω ve 3Ω) seri bağlandığında eşdeğer direnç kaç Ω'dür?","options":["2 Ω","9 Ω","18 Ω","3 Ω"],"correct_answer":"9 Ω"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"İki direnç (6Ω ve 3Ω) paralel bağlandığında eşdeğer direnç kaç Ω'dür?","options":["9 Ω","2 Ω","3 Ω","18 Ω"],"correct_answer":"2 Ω"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir optikte ışığın bir ortamdan başka bir ortama geçerken yön değiştirmesine ne denir?","options":["Yansıma","Kırılma","Saçılma","Girişim"],"correct_answer":"Kırılma"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir hareket halindeki tren içinde yolcu yukarı bir top atıyor. Top trenin referans çerçevesinde nereye düşer?","options":["Yolcunun önüne","Yolcunun arkasına","Yolcunun eline geri","Trenden dışarı"],"correct_answer":"Yolcunun eline geri"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir ses dalgasının frekansı artarsa, sesin algılanan perdesi nasıl değişir?","options":["Daha alçak olur","Daha yüksek olur","Aynı kalır","Ses kesilir"],"correct_answer":"Daha yüksek olur"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir ısıtıcı 220V gerilimde 2A akım çekiyorsa, harcadığı güç kaç Watt'tır?","options":["110 W","220 W","440 W","44 W"],"correct_answer":"440 W"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir cisim serbest düşmeye bırakıldığında 3 saniye sonra hızı kaç m/s'dir? (g ≈ 10 m/s²)","options":["10 m/s","20 m/s","30 m/s","15 m/s"],"correct_answer":"30 m/s"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir mıknatısın manyetik alan çizgileri aşağıdaki ifadelerden hangisinde doğru açıklanmıştır?","options":["Kuzey kutuptan güney kutba gider","Güney kutuptan kuzey kutba gider","İki kutup arasında düz çizgidir","Mıknatısdan bağımsızdır"],"correct_answer":"Kuzey kutuptan güney kutba gider"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir cisim 5 m yükseklikten serbest düşerse yere çarpma hızı kaç m/s'dir? (g ≈ 10 m/s²)","options":["5 m/s","10 m/s","15 m/s","20 m/s"],"correct_answer":"10 m/s"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir araba düz bir yolda sabit hızla giderken sürtünme kuvveti 500 N ve motor gücü 10 kW ise arabanın hızı kaç m/s'dir?","options":["10 m/s","20 m/s","50 m/s","5 m/s"],"correct_answer":"20 m/s"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir kabarcık hareket halinde iken iç basınca ne olur?","options":["Artar","Azalır","Aynı kalır","Sıfıra iner"],"correct_answer":"Azalır"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"İki cisim arasında kütleçekim kuvveti iki cisim arasındaki mesafe iki katına çıktığında nasıl değişir?","options":["İki kat artar","Yarıya iner","Dört kat artar","Dörtte birine iner"],"correct_answer":"Dörtte birine iner"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir dalga hareketinin dalga boyu 2 m ve frekansı 5 Hz ise dalga hızı kaç m/s'dir?","options":["2.5 m/s","7 m/s","10 m/s","3 m/s"],"correct_answer":"10 m/s"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir kondansatörün kapasitesi 10 µF ve gerilimi 12V ise depoladığı yük kaç Coulomb'dur?","options":["120 µC","1.2 µC","0.12 mC","12 µC"],"correct_answer":"120 µC"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir cismin kütlesi 2 kg ve hızı 3 m/s ise kinetik enerjisi kaç Joule'dur?","options":["3 J","6 J","9 J","18 J"],"correct_answer":"9 J"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir iletken telde akım 5 A ve telin direnci 4 Ω ise telde kaybedilen güç kaç Watt'tır?","options":["20 W","100 W","80 W","9 W"],"correct_answer":"100 W"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir gök cisminin yaydığı ışığın dalga boyu arttıkça, ışığın frekansı nasıl değişir?","options":["Artar","Azalır","Aynı kalır","Sıfır olur"],"correct_answer":"Azalır"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir kitap masada dururken kitaba etki eden yerçekimi kuvveti 20 N ise, masanın kitaba uyguladığı normal kuvvet kaç N'dir?","options":["0 N","10 N","20 N","40 N"],"correct_answer":"20 N"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir ışık ışını hava-su sınırında suya girerken nasıl kırılır?","options":["normale yaklaşarak","normalden uzaklaşarak","aynı doğrultuda devam ederek","Tam yansıma yaparak"],"correct_answer":"normale yaklaşarak"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir sarkaç 1 saniyede bir salınım yapıyorsa frekansı kaç Hz'dir?","options":["0.5 Hz","1 Hz","2 Hz","60 Hz"],"correct_answer":"1 Hz"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir araba virajı alırken hangi kuvvet merkezkaç kuvvetine karşı koyar?","options":["Sürtünme kuvveti","Yerçekimi kuvveti","Normal kuvvet","İvme kuvveti"],"correct_answer":"Sürtünme kuvveti"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir buz kalıbı eridiğinde hacmi nasıl değişir?","options":["Artar","Azalır","Aynı kalır","Önce artar sonra azalır"],"correct_answer":"Azalır"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir silindir içindeki gaz sabit sıcaklıkta hacminin yarısına sıkıştırılırsa basıncı nasıl değişir?","options":["Yarıya iner","İki kat artar","Aynı kalır","Dört kat artar"],"correct_answer":"İki kat artar"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir bataryanın EMK'sı 12V ve iç direnci 1Ω ise, 5Ω'luk dış dirence bağlandığında devreden geçen akım kaç A'dir?","options":["1 A","2 A","2.4 A","12 A"],"correct_answer":"2 A"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir ayna düzlem ayna ise, aynadaki görüntü için aşağıdakilerden hangisi yanlıştır?","options":["Sanaldır","Boyu eşittir","Eşit uzaklıktadır","Gerçektir"],"correct_answer":"Gerçektir"},{"subject":"fizik","subject_title":"Fizik Quiz","question":"Bir araba 20 m/s hızla giderken fren yaparak 4 saniyede duruyorsa frenleme ivmesi kaç m/s²'dir?","options":["4 m/s²","5 m/s²","6 m/s²","80 m/s²"],"correct_answer":"5 m/s²"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir atomun nötr olması için aşağıdakilerden hangisi doğru olmalıdır?","options":["Proton sayısı = Nötron sayısı","Proton sayısı = Elektron sayısı","Nötron sayısı = Elektron sayısı","Proton + Nötron = Elektron"],"correct_answer":"Proton sayısı = Elektron sayısı"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Aşağıdaki elementlerden hangisi soy gazdır?","options":["Oksijen","Hidrojen","Helyum","Karbon"],"correct_answer":"Helyum"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir çözeltinin pH değeri 3 ise, bu çözelti için aşağıdakilerden hangisi söylenebilir?","options":["Nötrdür","Baziktir","Asidiktir","Tuzdur"],"correct_answer":"Asidiktir"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Sodyum (Na) atomunun değerlik elektron sayısı kaçtır?","options":["1","2","7","8"],"correct_answer":"1"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir kimyasal tepkimede kütlenin korunumu yasası kime aittir?","options":["Newton","Lavoisier","Einstein","Boyle"],"correct_answer":"Lavoisier"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir atomun elektron diziliminde en dış kabukta 7 elektron varsa, bu atomun özelliği nedir?","options":["Metal","Ametal","Soy gaz","Geçiş metali"],"correct_answer":"Ametal"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Aşağıdakilerden hangisi kimyasal bir değişimdir?","options":["Buzun erimesi","Suyun buharlaşması","Demirin paslanması","Kağıdın yırtılması"],"correct_answer":"Demirin paslanması"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir bileşiğin molekül formülü H₂O ise, bu bileşikteki elementlerin kütle oranları nasıldır? (H=1, O=16)","options":["1:8","1:16","2:16","1:2"],"correct_answer":"1:8"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir iyonik bağda hangi tür elektron transferi gerçekleşir?","options":["Paylaşım","Transfer (metal → ametal)","Hiçbiri","Ortak kullanım"],"correct_answer":"Transfer (metal → ametal)"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir gazın basıncı, sıcaklığı ve hacmi arasındaki ilişkiyi veren gaz yasası hangisidir?","options":["Ohm yasası","İdeal gaz yasası (PV=nRT)","Newton yasası","Hooke yasası"],"correct_answer":"İdeal gaz yasası (PV=nRT)"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir çözeltiye biraz asit eklendiğinde pH nasıl değişir?","options":["Artar","Azalır","Aynı kalır","7'ye yaklaşır"],"correct_answer":"Azalır"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir elementin atom numarası, aşağıdakilerden hangisini belirtir?","options":["Nötron sayısı","Proton sayısı","Elektron sayısı (nötr atomda)","B ve C"],"correct_answer":"B ve C"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Klor (Cl) atomunun elektron diziliminde 3. kabukta kaç elektron vardır?","options":["5","6","7","8"],"correct_answer":"7"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Aşağıdaki bileşiklerden hangisi kovalent bağlıdır?","options":["NaCl","MgO","H₂O","KBr"],"correct_answer":"H₂O"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir tepkimenin denkleştirilmesinde korunması gereken yasalar aşağıdakilerden hangileridir?","options":["Kütlenin korunumu","Atom sayısının korunumu","Elektron sayısının korunumu","A ve B"],"correct_answer":"A ve B"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir maddenin 1 molü kaç taneciğe eşittir?","options":["6.022 × 10²³","6.022 × 10²²","3.011 × 10²³","1.2 × 10²⁴"],"correct_answer":"6.022 × 10²³"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir bileşiğin empirik formülü CH₂ ise ve molekül ağırlığı 28 g/mol ise, molekül formülü nedir? (C=12, H=1)","options":["CH₂","C₂H₄","C₃H₆","C₄H₈"],"correct_answer":"C₂H₄"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir çözeltide 0.1 M HCl varsa, H⁺ iyonu konsantrasyonu kaç M'dir?","options":["0.01 M","0.1 M","1 M","0.001 M"],"correct_answer":"0.1 M"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir metalin oksijenle tepkimesiyle oluşan bileşik aşağıdakilerden hangisi olabilir?","options":["CO₂","Na₂O","H₂O","NO₂"],"correct_answer":"Na₂O"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir tepkimenin aktive enerjisi neyi temsil eder?","options":["Tepkimenin açığa çıkardığı enerji","Tepkimenin başlaması için gereken enerji","Tepkimenin toplam enerjisi","Ürünlerin enerjisi"],"correct_answer":"Tepkimenin başlaması için gereken enerji"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Periyodik tabloda bir grupta aşağı yukarı gidildikçe atom yarıçapı nasıl değişir?","options":["Artar","Azalır","Aynı kalır","Önce artar sonra azalır"],"correct_answer":"Artar"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Periyodik tabloda bir periyotta soldan sağa gidildikçe metalik özellik nasıl değişir?","options":["Artar","Azalır","Aynı kalır","Düzenli değişmez"],"correct_answer":"Azalır"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir gaz sabit hacimde ısındığında basıncı nasıl değişir?","options":["Artar","Azalır","Aynı kalır","Sıfıra iner"],"correct_answer":"Artar"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir bileşikteki elementlerin kütle yüzdelerinden bileşiğin formülü bulunduğunda, önce hangi formül hesaplanır?","options":["Molekül formülü","Empirik (en basit) formül","Yapısal formül","İyonik formül"],"correct_answer":"Empirik (en basit) formül"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir sulu çözeltide [H⁺] = 10⁻⁵ M ise pH kaçtır?","options":["3","5","7","9"],"correct_answer":"5"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir nötr atomdan bir elektron çıkarıldığında oluşan iyon aşağıdakilerden hangisidir?","options":["Anyon","Katyon","Molekül","İzotop"],"correct_answer":"Katyon"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir kimyasal bağda iki atom arasında elektron paylaşımı olduğunda, bu bağ türü nedir?","options":["İyonik bağ","Kovalent bağ","Metalik bağ","Hidrojen bağı"],"correct_answer":"Kovalent bağ"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir elementin izotopları aşağıdakilerden hangisinde farklıdır?","options":["Proton sayısı","Nötron sayısı","Elektron sayısı","Atom numarası"],"correct_answer":"Nötron sayısı"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir gaz 0°C ve 1 atm'de 22.4 L hacim kaplıyorsa, bu gazın miktarı kaç moldür?","options":["0.5 mol","1 mol","2 mol","22.4 mol"],"correct_answer":"1 mol"},{"subject":"kimya","subject_title":"Kimya Quiz","question":"Bir tepkimede katalizörün görevi nedir?","options":["Tepkimeyi yavaşlatır","Aktive enerjisini düşürerek tepkimeyi hızlandırır","Ürün miktarını artırır","Tepkimeyi durdurur"],"correct_answer":"Aktive enerjisini düşürerek tepkimeyi hızlandırır"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Fotosentez olayında bitkiler aşağıdakilerden hangisini üretir?","options":["Karbondioksit ve su","Glikoz ve oksijen","Azot ve hidrojen","Metan ve karbondioksit"],"correct_answer":"Glikoz ve oksijen"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"DNA molekülünün yapısında aşağıdaki bazlardan hangisi bulunmaz?","options":["Adenin","Guanin","Sitozin","Urasil"],"correct_answer":"Urasil"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Mitokondri'nin hücredeki temel görevi nedir?","options":["Protein sentezi","Enerji (ATP) üretimi","Atık madde parçalanması","Fotosentez"],"correct_answer":"Enerji (ATP) üretimi"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Aşağıdakilerden hangisi bir bitki hücresinde bulunur ama hayvan hücresinde bulunmaz?","options":["Çekirdek","Mitokondri","Hücre çeperi (duvarı)","Ribozom"],"correct_answer":"Hücre çeperi (duvarı)"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"İnsanda kanı vücuda pompalayan organ hangisidir?","options":["Akciğer","Karaciğer","Kalp","Böbrek"],"correct_answer":"Kalp"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir genin ifade edilmesi (protein üretimi) sürecine ne denir?","options":["Replikasyon","Transkripsiyon ve translasyon","Mutasyon","Fotosentez"],"correct_answer":"Transkripsiyon ve translasyon"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Mayoz bölünme sonucu kaç hücre oluşur ve kromozom sayısı nasıl değişir?","options":["2 hücre, aynı kromozom sayısı","4 hücre, kromozom sayısı yarıya iner","4 hücre, kromozom sayısı iki katına çıkar","2 hücre, kromozom sayısı yarıya iner"],"correct_answer":"4 hücre, kromozom sayısı yarıya iner"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlının çevresine uyum sağlaması için doğal seleksiyon mekanizmasını öneren bilim insanı kimdir?","options":["Mendel","Darwin","Pasteur","Linne"],"correct_answer":"Darwin"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir protein molekülünün birincil yapısı neyi belirtir?","options":["Üç boyutlu katlanmış şekil","Aminoasit dizilim sırası","İki veya daha fazla polipeptid zinciri","Proteinin işlevi"],"correct_answer":"Aminoasit dizilim sırası"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"İnsanda oksijen taşıyan kan hücresi aşağıdakilerden hangisidir?","options":["Akyuvar (lökosit)","Alyuvar (eritrosit)","Trombosit","Plazma"],"correct_answer":"Alyuvar (eritrosit)"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir besin zincirinde üretici olarak aşağıdakilerden hangisi görev yapar?","options":["Otçul hayvan","Etçil hayvan","Yeşil bitki","Ayrıştırıcı"],"correct_answer":"Yeşil bitki"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir hücrede protein sentezi aşağıdaki organellerden hangisinde gerçekleşir?","options":["Mitokondri","Ribozom","Golgi cisimciği","Lizozom"],"correct_answer":"Ribozom"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir nöronun bir başka nörona veya hücreye iletişim kurduğu bağlantı noktasına ne denir?","options":["Sinaps","Akson","Dendrit","Miyelin kılıf"],"correct_answer":"Sinaps"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir insanın kan grubu AB ise, aşağıdaki kan gruplarından hangisini alabilir?","options":["Sadece A","Sadece B","A ve B","Tüm kan grupları"],"correct_answer":"A ve B"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir DNA molekülünde adenin oranı %30 ise, guanin oranı kaçtır?","options":["20%","30%","40%","50%"],"correct_answer":"20%"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir bitkinin köklerinden yapraklarına su taşıyan doku aşağıdakilerden hangisidir?","options":["Floem","Ksilem","Epidermis","Kambiyum"],"correct_answer":"Ksilem"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlının kalıtsal özelliklerini belirleyen molekül hangisidir?","options":["Protein","DNA","Lipid","Karbonhidrat"],"correct_answer":"DNA"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir hücrede sindirilmiş maddeleri paketleyip gönderen organel hangisidir?","options":["Ribozom","Golgi cisimciği","Mitokondri","Çekirdek"],"correct_answer":"Golgi cisimciği"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlı hücrede oksijenli solunumun gerçekleştiği organel hangisidir?","options":["Kloroplast","Mitokondri","Ribozom","Golgi"],"correct_answer":"Mitokondri"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir hücre bölünmesinde kromozomların ikiye ayrıldığı evre hangisidir?","options":["İnterfaz","Anafaz","Metafaz","Telofaz"],"correct_answer":"Anafaz"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir kalıtım özelliğinde bir genin farklı versiyonlarına ne denir?","options":["Kromozom","Alel","Genom","Mutasyon"],"correct_answer":"Alel"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir ekosistemde enerji akışı aşağıdaki yönlarden hangisine gerçekleşir?","options":["Üretici → Ayrıştırıcı → Tüketici","Üretici → Tüketici → Ayrıştırıcı","Ayrıştırıcı → Üretici → Tüketici","Tüketici → Üretici → Ayrıştırıcı"],"correct_answer":"Üretici → Tüketici → Ayrıştırıcı"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir insanda idrar üretiminden sorumlu organ hangisidir?","options":["Karaciğer","Böbrek","Akciğer","Dalak"],"correct_answer":"Böbrek"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlının bireysel gelişimi sırasında hücre sayısının artması süreci nedir?","options":["Büyüme","Üreme","Solunum","Beslenme"],"correct_answer":"Büyüme"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir proteinin üç boyutlu şekli aşağıdakilerden hangisine bağlıdır?","options":["Aminoasit sayısı","Aminoasit dizilimi","Proteinin rengi","Proteinin büyüklüğü"],"correct_answer":"Aminoasit dizilimi"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir insanda şeker hastalığının (diyabet) temel nedeni nedir?","options":["Tiroksin eksikliği","İnsülin eksikliği veya direnci","Adrenalin fazlalığı","Büyüme hormonu eksikliği"],"correct_answer":"İnsülin eksikliği veya direnci"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir bitkide döllenme sonrası tohumu oluşturan yapı hangisidir?","options":["Yumurtalık","Toz kesesi","Taç yaprak","Dişicik borusu"],"correct_answer":"Yumurtalık"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlının bireysel gelişiminde zigottan başlayıp ergin bireye ulaşmasına ne denir?","options":["Üreme","Büyüme ve gelişme","Döllenme","Mutasyon"],"correct_answer":"Büyüme ve gelişme"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir hücrede atık maddelerin parçalanmasından sorumlu organel hangisidir?","options":["Ribozom","Lizozom","Mitokondri","Golgi"],"correct_answer":"Lizozom"},{"subject":"biyoloji","subject_title":"Biyoloji Quiz","question":"Bir canlının çevreye uyum sağlaması için bazı özelliklerinin değişmesi süreci nedir?","options":["Mutasyon","Adaptasyon","Üreme","Büyüme"],"correct_answer":"Adaptasyon"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir dik üçgende dik kenarlar 3 ve 4 birim ise hipotenüs kaç birimdir?","options":["5","6","7","8"],"correct_answer":"5"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"x² - 5x + 6 = 0 denkleminin kökleri nedir?","options":["x = 2 ve x = 3","x = 1 ve x = 6","x = -2 ve x = -3","x = -1 ve x = -6"],"correct_answer":"x = 2 ve x = 3"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir çemberin yarıçapı 5 birim ise alanı kaç birim karedir? (π ≈ 3.14)","options":["15.7","31.4","78.5","157"],"correct_answer":"78.5"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir fonksiyon f(x) = 2x + 3 ise, f(5) kaçtır?","options":["8","10","13","16"],"correct_answer":"13"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"log₂(8) kaçtır?","options":["2","3","4","8"],"correct_answer":"3"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir üçgenin iç açıları toplamı kaç derecedir?","options":["90°","180°","270°","360°"],"correct_answer":"180°"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir küpün bir kenarı 3 birim ise hacmi kaç birim küptür?","options":["9","12","18","27"],"correct_answer":"27"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir doğrusal denklem sisteminde 2x + y = 7 ve x - y = 2 ise x kaçtır?","options":["1","2","3","4"],"correct_answer":"3"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Sin(30°) + cos(60°) kaçtır?","options":["0","0.5","1","1.5"],"correct_answer":"1"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir dizide 2, 4, 8, 16, ... pattern ise 6. terim kaçtır?","options":["32","64","128","256"],"correct_answer":"64"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir fonksiyonun türevi f(x) = x³ + 2x ise, f'(x) nedir?","options":["3x² + 2","x² + 2","3x + 2","x³ + 2"],"correct_answer":"3x² + 2"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir kürenin yarıçapı 2 birim ise yüzey alanı kaçtır? (π ≈ 3.14)","options":["12.56","25.12","50.24","100.48"],"correct_answer":"50.24"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"10! / 8! kaçtır?","options":["10","80","90","100"],"correct_answer":"90"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir ikinci dereceden denklem 2x² - 8 = 0 ise x nedir?","options":["x = ±2","x = ±4","x = ±8","x = 2"],"correct_answer":"x = ±2"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir üçgenin tabanı 8 ve yüksekliği 5 ise alanı kaçtır?","options":["13","20","40","16"],"correct_answer":"20"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir düzlemde iki doğru kesiştiğinde oluşan zıt açılar nasıl ilişkilidir?","options":["Eştir","Tümlerdir","Bütünlerdir","İlişkisizdir"],"correct_answer":"Eştir"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir sayının %20'si 30 ise sayı kaçtır?","options":["120","150","180","200"],"correct_answer":"150"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir fonksiyon f(x) = x² - 4x + 3 ise, f(1) kaçtır?","options":["0","1","-1","3"],"correct_answer":"0"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir silindirin taban yarıçapı 3 ve yüksekliği 5 ise hacmi kaçtır? (π ≈ 3.14)","options":["47.1","141.3","94.2","188.4"],"correct_answer":"141.3"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir dizide 5, 10, 15, 20, ... pattern ise 10. terim kaçtır?","options":["45","50","55","100"],"correct_answer":"50"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"cos²(x) + sin²(x) kaçtır?","options":["0","1","2","x'e bağlı"],"correct_answer":"1"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir sayının karesi kendisine eşitse, bu sayı aşağıdakilerden hangisi olabilir?","options":["0 ve 1","1 ve 2","0 ve -1","Sadece 1"],"correct_answer":"0 ve 1"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir çokgenin iç açıları toplamı 1080° ise kaç kenarlıdır?","options":["6","7","8","9"],"correct_answer":"8"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir doğrunun denklemi y = 3x - 2 ise, eğimi kaçtır?","options":["-2","2","3","-3"],"correct_answer":"3"},{"subject":"matematik","subject_title":"Matematik Quiz","question":"Bir permütasyonda 5 farklı kitap bir rafa kaç farklı şekilde dizilebilir?","options":["25","60","120","720"],"correct_answer":"120"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Güneş sistemimizde kaç gezegen vardır?","options":["7","8","9","10"],"correct_answer":"8"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Güneş enerjisini üreten tepkime nedir?","options":["Kimyasal yanma","Nükleer füzyon","Nükleer fisyon","Elektromanyetik indüksiyon"],"correct_answer":"Nükleer füzyon"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir ışık yılı neyi ölçer?","options":["Zamanı","Mesafeyi","Hızı","Kütleyi"],"correct_answer":"Mesafeyi"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Ay'ın evrelerinden dolunayda Ay nasıl görünür?","options":["Tamamen karanlık","Tamamen parlak (tam disk)","Yarım parlak","Hilal şeklinde"],"correct_answer":"Tamamen parlak (tam disk)"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir yıldızın parlaklığını belirleyen temel faktörler aşağıdakilerden hangileridir?","options":["Boyut ve sıcaklık","Uzaklık ve renk","Yaş ve kütle","Boyut, sıcaklık ve uzaklık"],"correct_answer":"Boyut, sıcaklık ve uzaklık"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Güneş sistemimizdeki en büyük gezegen hangisidir?","options":["Satürn","Jüpiter","Uranüs","Neptün"],"correct_answer":"Jüpiter"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir gök cisminin ışığı bükerek arkasındaki cisimleri büyütmesi olayına ne denir?","options":["Yansıma","Kırınım (Gravitasyon lens)","Saçılma","Girişim"],"correct_answer":"Kırınım (Gravitasyon lens)"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Dünya'nın ekseni eğikliği aşağıdaki olaylardan hangisine neden olur?","options":["Gel-git","Mevsimler","Güneş tutulması","Ay tutulması"],"correct_answer":"Mevsimler"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir kara deliğin olay ufku (event horizon) nedir?","options":["Kara deliğin merkezi","Işığın bile kaçamadığı sınır","Kara deliğin dış görünür yüzeyi","Kara deliğin uyduları"],"correct_answer":"Işığın bile kaçamadığı sınır"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Samanyolu galaksisinin merkezindeki süper kütleli gök cisminin türü nedir?","options":["Nötron yıldızı","Beyaz cüce","Kara delik (Sgr A*)","Kırmızı dev"],"correct_answer":"Kara delik (Sgr A*)"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir göktaşı (meteor) Dünya'ya ulaştığında ne ad alır?","options":["Kuyruklu yıldız","Asteroit","Meteorit","Uydu"],"correct_answer":"Meteorit"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir yıldızın yaşam döngüsünde kırmızı dev aşamasından sonra oluşabilecek gök cismi aşağıdakilerden hangisidir?","options":["Kara delik","Beyaz cüce","Nötron yıldızı","Hepsi"],"correct_answer":"Hepsi"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir gezegenin Güneş etrafındaki bir turuna ne denir?","options":["Dönme (rotation)","Devrim (revolution)","İklim değişimi","Gel-git"],"correct_answer":"Devrim (revolution)"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir gökbilimci, bir galaksinin bizden uzaklaştığını hangi gözlemle anlar?","options":["Rengi maviye kayar","Işığı kırmızıya kayar (redshift)","Parlaklığı artar","Boyutu büyür"],"correct_answer":"Işığı kırmızıya kayar (redshift)"},{"subject":"astronomi","subject_title":"Astronomi Quiz","question":"Bir yıldızın rengi neyi belirler?","options":["Yaşını","Uzaklığını","Sıcaklığını","Kütlesini"],"correct_answer":"Sıcaklığını"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel hipotez test edilebilir olmalı ve aşağıdaki özelliklerden hangisine sahip olmalıdır?","options":["Kesinlikle doğru olmalı","Yanlışlanabilir (falsifiable) olmalı","Herkes tarafından kabul görmeli","Yasa tarafından onaylanmalı"],"correct_answer":"Yanlışlanabilir (falsifiable) olmalı"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyde değiştirilmeyen ve sabit tutulan faktörlere ne denir?","options":["Bağımsız değişken","Bağımlı değişken","Kontrol değişkeni","Hipotez"],"correct_answer":"Kontrol değişkeni"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel kuram (teori) aşağıdakilerden hangisidir?","options":["Sadece bir tahmin","Kapsamlı testlerden geçmiş açıklama","Bir hipotez ile aynı şey","Kanıtlanmamış bir fikir"],"correct_answer":"Kapsamlı testlerden geçmiş açıklama"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyde ölçülen ve başka bir faktöre bağlı olarak değişen faktöre ne denir?","options":["Bağımsız değişken","Bağımlı değişken","Kontrol grubu","Hipotez"],"correct_answer":"Bağımlı değişken"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı bir deney sonucunu diğer bilim insanlarıyla paylaşmak için aşağıdakilerden hangisini yapar?","options":["Sonucu gizli tutar","Hakemli bir dergide yayınlar","Sadece öğrencilerine anlatır","Sonucu bir kitaba yazar"],"correct_answer":"Hakemli bir dergide yayınlar"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setinde en sık tekrar eden değere ne denir?","options":["Ortalama","Medyan","Mod","Aralık"],"correct_answer":"Mod"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyde iki grup arasındaki tek fark bağımsız değişken ise, bu gruplara ne denir?","options":["Kontrol ve deney grubu","Öncül ve ardıl grup","Rastgele ve seçilmiş grup","Aktif ve pasif grup"],"correct_answer":"Kontrol ve deney grubu"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı, gözlemlerine dayanarak bir açıklama önerdiğinde bu açıklamaya ne denir?","options":["Kuram","Yasa","Hipotez","Aksiyom"],"correct_answer":"Hipotez"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setindeki değerlerin ortalamadan ne kadar saptığını ölçen istatistiksel değer nedir?","options":["Medyan","Standart sapma","Mod","Aralık"],"correct_answer":"Standart sapma"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel yasa (law) aşağıdakilerden hangisini yapar?","options":["Bir olayı açıklar","Bir olayın nasıl olduğunu betimler","Yeni bir hipotez önerir","Bir kuramı çürütür"],"correct_answer":"Bir olayın nasıl olduğunu betimler"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir grafikte x eksenindeki değişken genellikle aşağıdakilerden hangisidir?","options":["Bağımlı değişken","Bağımsız değişken","Kontrol değişkeni","Sabit değer"],"correct_answer":"Bağımsız değişken"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir deneyin sonuçları tekrarlanabilir olması neden önemlidir?","options":["Daha uzun sürer","Sonuçların güvenilir olduğunu gösterir","Daha fazla para harcanır","Daha az insan gerektirir"],"correct_answer":"Sonuçların güvenilir olduğunu gösterir"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir veri setinde en büyük ve en küçük değer arasındaki farka ne denir?","options":["Ortalama","Medyan","Aralık (range)","Mod"],"correct_answer":"Aralık (range)"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilim insanı bir deneyin sonucunu raporlarken aşağıdakilerden hangisini yapmamalıdır?","options":["Verileri doğru rapor eder","Yöntemi açıklar","Verileri kendi hipotezini desteklemek için çarpıtır","Sonuçların sınırlamalarını belirtir"],"correct_answer":"Verileri kendi hipotezini desteklemek için çarpıtır"},{"subject":"genel-bilim","subject_title":"Genel Bilim Quiz","question":"Bir bilimsel modelin amacı aşağıdakilerden hangisidir?","options":["Karmaşık bir sistemi basitleştirerek anlamak","Gerçeğin tam bir kopyasını oluşturmak","Sadece güzel görünmek","Hipotezleri çürütmek"],"correct_answer":"Karmaşık bir sistemi basitleştirerek anlamak"}]$btkquiz_seed$::jsonb) as seed(subject text, subject_title text, question text, options text[], correct_answer text)
on conflict (konu, soru) do update
set baslik = excluded.baslik, secenekler = excluded.secenekler, dogru = excluded.dogru;

drop policy if exists "Kullanıcı kendi skorunu ekleyebilir" on public.quiz_scores;
drop policy if exists "Authenticated users can insert own scores" on public.quiz_scores;
revoke insert on public.quiz_scores from public, anon, authenticated;

drop function if exists public.quiz_skoru_kaydet(text, jsonb);
create function public.quiz_skoru_kaydet(p_konu text, p_cevaplar jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_uid uuid := auth.uid();
    v_total integer;
    v_correct integer := 0;
    v_title text;
    v_question text;
    v_answer text;
    v_options text[];
    v_expected text;
    v_seen text[] := array[]::text[];
    v_row record;
    v_score_id bigint;
begin
    if v_uid is null then
        raise exception 'Authentication required.' using errcode = '42501';
    end if;
    if p_konu is null or char_length(p_konu) > 80
       or p_cevaplar is null or jsonb_typeof(p_cevaplar) <> 'array' then
        raise exception 'Invalid quiz submission.' using errcode = '22023';
    end if;

    v_total := jsonb_array_length(p_cevaplar);
    if v_total < 1 or v_total > 8 then
        raise exception 'A quiz round must contain 1 to 8 questions.' using errcode = '22023';
    end if;
    if (select count(*) from public.quiz_scores
        where user_id = v_uid and created_at > now() - interval '1 minute') >= 10 then
        raise exception 'Too many quiz submissions; retry later.' using errcode = '22023';
    end if;

    for v_row in select value from jsonb_array_elements(p_cevaplar) loop
        v_question := btrim(coalesce(v_row.value ->> 'question', ''));
        v_answer := btrim(coalesce(v_row.value ->> 'answer', ''));
        if char_length(v_question) < 5 or char_length(v_question) > 600 or char_length(v_answer) > 200 then
            raise exception 'Invalid quiz answer format.' using errcode = '22023';
        end if;
        if exists (
            select 1 from unnest(v_seen) prior
            where lower(regexp_replace(btrim(prior), '\s+', ' ', 'g')) = lower(regexp_replace(v_question, '\s+', ' ', 'g'))
        ) then
            raise exception 'A question cannot be submitted more than once.' using errcode = '22023';
        end if;
        v_seen := array_append(v_seen, v_question);

        select k.baslik, k.secenekler, k.dogru
        into v_title, v_options, v_expected
        from public.quiz_skor_cevap_anahtari k
        where k.konu = p_konu
          and lower(regexp_replace(btrim(k.soru), '\s+', ' ', 'g')) = lower(regexp_replace(v_question, '\s+', ' ', 'g'))
        limit 1;

        if not found then
            select t.baslik, q.secenekler, q.dogru
            into v_title, v_options, v_expected
            from public.quiz_sorulari q
            join public.quiz_konulari t on t.slug = q.konu and t.aktif
            where q.konu = p_konu and q.aktif
              and lower(regexp_replace(btrim(q.soru), '\s+', ' ', 'g')) = lower(regexp_replace(v_question, '\s+', ' ', 'g'))
            order by q.id
            limit 1;
        end if;

        if not found then
            raise exception 'Question does not belong to this quiz topic.' using errcode = '22023';
        end if;
        if v_answer <> '' and not (v_answer = any(v_options)) then
            raise exception 'Answer is not one of the question options.' using errcode = '22023';
        end if;
        if v_answer = v_expected then v_correct := v_correct + 1; end if;
    end loop;

    if exists (select 1 from public.quiz_skor_cevap_anahtari where konu = p_konu) then
        select baslik into v_title from public.quiz_skor_cevap_anahtari where konu = p_konu limit 1;
    else
        select baslik into v_title from public.quiz_konulari where slug = p_konu and aktif;
    end if;
    if v_title is null then
        raise exception 'Quiz topic is missing or inactive.' using errcode = '22023';
    end if;

    insert into public.quiz_scores (user_id, subject, subject_title, score)
    values (v_uid, p_konu, v_title, v_correct * 25)
    returning id into v_score_id;

    return jsonb_build_object('id', v_score_id, 'score', v_correct * 25, 'correct', v_correct, 'total', v_total);
end;
$$;

revoke all on function public.quiz_skoru_kaydet(text, jsonb) from public, anon;
grant execute on function public.quiz_skoru_kaydet(text, jsonb) to authenticated;
